source('R/stile.R')
z<-data.frame(k=0:10,p=dbinom(0:10,10,.2))
salva('M04','F01',ggplot(z,aes(k,p))+geom_col(fill=geo[1],width=.7)+geom_vline(xintercept=2,colour=geo[2],linetype=2)+scale_x_continuous(breaks=c(0,2,4,6,8,10))+labs(x='Successi K',y='Probabilità'))
z<-data.frame(prev=seq(.001,.6,length.out=300));z$post<-.9*z$prev/(.9*z$prev+.05*(1-z$prev))
salva('M04','F02',ggplot(z,aes(prev,post))+geom_line(colour=geo[1],linewidth=1.1)+geom_point(data=data.frame(prev=.1,post=2/3),colour=geo[2],size=3)+labs(x='Prevalenza P(A)',y='P(A | segnale)'))
z<-do.call(rbind,lapply(c(20,100),function(n)data.frame(prop=(0:n)/n,p=dbinom(0:n,n,.3),N=factor(paste('n =',n),levels=c('n = 20','n = 100')))))
salva('M04','F03',ggplot(z,aes(prop,p))+geom_segment(aes(xend=prop,yend=0),colour=geo[1],linewidth=.8)+facet_wrap(~N,ncol=1)+scale_y_continuous(breaks=c(0,.1,.2))+labs(x='Proporzione K/n',y='Probabilità'),h=4.2)
z<-do.call(rbind,lapply(c(1,4),function(l)data.frame(k=0:12,p=dpois(0:12,l),lambda=paste('λ =',l))))
salva('M04','F04',ggplot(z,aes(k,p,colour=lambda))+geom_line(linewidth=1)+geom_point(size=2)+scale_colour_manual(values=geo[1:2])+scale_x_continuous(breaks=seq(0,12,3))+labs(x='Conteggio K',y='Probabilità'))
z<-do.call(rbind,lapply(c(1,2),function(s)data.frame(x=seq(3,17,length.out=500),y=dnorm(seq(3,17,length.out=500),10,s),Sigma=paste('σ =',s))))
salva('M04','F05',ggplot(z,aes(x,y,colour=Sigma))+geom_line(linewidth=1.1)+scale_colour_manual(values=geo[1:2])+labs(x='Misura',y='Densità'))
z<-data.frame(x=seq(-4,4,length.out=1001));z$y<-dnorm(z$x);cut<-qnorm(.975)
salva('M04','F06',ggplot(z,aes(x,y))+geom_area(data=z[abs(z$x)<=cut,],fill=geo[1],alpha=.3)+geom_line(colour=geo[1],linewidth=1)+geom_vline(xintercept=c(-cut,cut),colour=geo[2],linetype=2)+scale_x_continuous(breaks=c(-2,0,2))+labs(x='Scarto standardizzato z',y='Densità'))
z<-do.call(rbind,lapply(c(.3,.8),function(s)data.frame(x=seq(.01,5,length.out=500),y=dlnorm(seq(.01,5,length.out=500),0,s),Sigma=paste('σ log =',s))))
salva('M04','F07',ggplot(z,aes(x,y,colour=Sigma))+geom_line(linewidth=1)+scale_colour_manual(values=geo[1:2])+labs(x='Valore positivo',y='Densità'))
u<-seq(-4,7,length.out=500);z<-rbind(data.frame(x=u,y=.7*dnorm(u,0,1),Curva='Componente 1'),data.frame(x=u,y=.3*dnorm(u,3.5,.7),Curva='Componente 2'),data.frame(x=u,y=.7*dnorm(u)+.3*dnorm(u,3.5,.7),Curva='Miscela'))
salva('M04','F08',ggplot(z,aes(x,y))+geom_area(data=z[z$Curva!='Miscela',],aes(fill=Curva),alpha=.25,position='identity')+geom_line(data=z[z$Curva=='Miscela',],colour=geo[3],linewidth=1.2)+scale_fill_manual(values=geo[1:2])+labs(x='Valore',y='Densità')+theme(plot.margin=margin(9,25,7,8)))
set.seed(409);B<-50000L;k<-rbinom(B,20,.3);prob<-pbinom(7,20,.3,lower.tail=FALSE)
z<-data.frame(b=seq_len(B),p=cumsum(k>=8)/seq_len(B));z<-z[z$b>=100,]
salva('M04','F09',ggplot(z,aes(b,p))+geom_line(colour=geo[1],linewidth=.7)+geom_hline(yintercept=prob,colour=geo[2],linetype=2)+scale_x_log10(breaks=c(100,1000,10000),labels=c('100','1.000','10.000'))+labs(x='Repliche B',y='Probabilità stimata'))
rpos<-function(n,mu,s){v<-log1p((s/mu)^2);rlnorm(n,log(mu)-v/2,sqrt(v))}
set.seed(410);mass<-rpos(B,106,1);v1<-rpos(B,40,.5);v2<-rpos(B,40,4)
z<-rbind(data.frame(rho=mass/v1,Scenario='u(V) = 0,5'),data.frame(rho=mass/v2,Scenario='u(V) = 4'))
salva('M04','F10',ggplot(z,aes(rho,colour=Scenario))+geom_density(linewidth=1)+scale_colour_manual(values=geo[1:2])+labs(x='Densità (g/cm³)',y='Densità di probabilità'))
verifica('massa binomiale normalizzata',abs(sum(dbinom(0:10,10,.2))-1)<1e-14)
verifica('Bayes',abs(.09/(.09+.045)-2/3)<1e-14)
verifica('area normale',abs((pnorm(2)-pnorm(-2))-.9544997361)<1e-9)
verifica('coda binomiale simulata',abs(mean(k>=8)-prob)<6*sqrt(prob*(1-prob)/B))
verifica('ingressi positivi',all(mass>0) && all(v1>0) && all(v2>0))
# E[M/V] per lognormali indipendenti è E[M]*(1+CV_V^2)/E[V].
atteso<-106/40*(1+(.5/40)^2);se<-sd(mass/v1)/sqrt(B)
verifica('atteso del rapporto',abs(mean(mass/v1)-atteso)<6*se)
verifica('sensibilità volume',sd(mass/v2)>sd(mass/v1))
